#' Compare designs
#'
#' Simulates one scenario under several study designs from the same 
#' superpopulation (same seed and student key) and compares what each design 
#' estimates, with its 95\% confidence interval, against the true values. The 
#' studies can be opened as one dataset with a design column.
#' 
#'
#' @examples
#' \donttest{
#' # in R, use the engine directly:
#' # sc <- studysim:::load_scenario(studysim:::builtin_library(), "breast_cancer_risk")
#' # studysim:::compare_designs(sc, "breast_cancer", c("case_control", "cohort"), n = 1000)
#'}
#' @param data .
#' @param libName name of the custom library file read by the Browse button
#'   (display only)
#' @param libContent base64 of the custom library file (JSON, YAML, Excel or
#'   zip)
#' @param scenario scenario id
#' @param outcome outcome id; empty means the scenario's first outcome
#' @param designs designs to compare; those that do not fit the outcome are
#'   skipped
#' @param measured one entry per scenario variable, list(var = name, include =
#'   TRUE/FALSE, form =
#'   "continuous"/"median"/"tertiles"/"quartiles"/"quintiles"/"cuts"/"log2"/"log10"/"scale",
#'   cuts = "18.5, 25, 30" or "10\%, 90\%", or the divisor for scale, e.g.
#'   "10"); included variables are in the dataset, the others are unmeasured
#'   (they still act); form groups a continuous variable (quantiles from the
#'   sample)
#' @param n number of participants (cases plus controls in case-control
#'   designs)
#' @param ccRatio case-control designs, controls per case (1 to 10); empty:
#'   the scenario's value
#' @param followup in the outcome's time units; empty: the scenario's value
#' @param loss empty: the scenario's value (2\% by default)
#' @param seed .
#' @param studentKey any text (e.g. a student ID); each key gives a different
#'   dataset (capitals and surrounding spaces are ignored)
#' @param showExpected also simulate one large study per design and show its
#'   estimates
#' @param showPlot .
#' @param showDag .
#' @param dagValues .
#' @param openData .
#' @param exportCsv .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$notice} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$studies} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$estimates} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$dag} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$plot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$openState} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$csvState} \tab \tab \tab \tab \tab a table \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$studies$asDF}
#'
#' \code{as.data.frame(results$studies)}
#'
#' @export
simCompare <- function(
    data,
    libName = "",
    libContent = "",
    scenario = "breast_cancer_risk",
    outcome = "",
    designs = list(
                "case_control",
                "matched_cc",
                "cohort"),
    measured = list(),
    n = 500,
    ccRatio = "",
    followup = "",
    loss = "",
    seed = 1,
    studentKey = "",
    showExpected = FALSE,
    showPlot = TRUE,
    showDag = TRUE,
    dagValues = FALSE,
    openData = FALSE,
    exportCsv = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("simCompare requires jmvcore to be installed (restart may be required)")

    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame())


    options <- simCompareOptions$new(
        libName = libName,
        libContent = libContent,
        scenario = scenario,
        outcome = outcome,
        designs = designs,
        measured = measured,
        n = n,
        ccRatio = ccRatio,
        followup = followup,
        loss = loss,
        seed = seed,
        studentKey = studentKey,
        showExpected = showExpected,
        showPlot = showPlot,
        showDag = showDag,
        dagValues = dagValues,
        openData = openData,
        exportCsv = exportCsv)

    analysis <- simCompareClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

